-- OrderOn: run with Supabase CLI. Amounts are integer paise, all dates UTC.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade, role text not null default 'customer' check(role in ('customer','merchant','admin')), name text not null, phone text, gender text, email text);
create table public.institutions(id uuid primary key default gen_random_uuid(),name text not null);
create table public.campuses(id uuid primary key default gen_random_uuid(),institution_id uuid references institutions,name text not null);
create table public.merchants(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles,slug text unique not null,name text not null,description text not null default '',type text default 'canteen',category text default '',is_on_campus boolean default true,campus_id uuid references campuses,campus text default '',building text default '',address text default '',city text default '',state text default '',pin text default '',lat numeric,lng numeric,veg_type text default 'both',open_days text[] default array['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],hours text default '08:00–20:00',accepting_orders boolean default false,rush_extra_minutes int default 0,avg_prep_minutes int default 12 check(avg_prep_minutes between 1 and 120),supports_pickup boolean default true,supports_dine_in boolean default true,pay_at_counter_enabled boolean default false,status text default 'pending' check(status in ('pending','approved','rejected','suspended')),gateway_account_ref text,image text default '');
create table merchant_hours(id uuid primary key default gen_random_uuid(),merchant_id uuid references merchants,day int check(day between 0 and 6),opens time,closes time);
create table menu_categories(id uuid primary key default gen_random_uuid(),merchant_id uuid references merchants,name text not null,sort int default 0);
create table menu_items(id uuid primary key default gen_random_uuid(),merchant_id uuid not null references merchants,category_id uuid references menu_categories,category text not null,name text not null,description text default '',price_minor int not null check(price_minor>0),is_veg boolean default true,image text default '',image_path text, in_stock boolean default true,sort int default 0,variants jsonb not null default '[]');
create table menu_variants(id uuid primary key default gen_random_uuid(),item_id uuid references menu_items,name text not null,price_minor int not null check(price_minor>0));
create table merchant_tables(id uuid primary key default gen_random_uuid(),merchant_id uuid not null references merchants,label text not null,enabled boolean default true,deleted_at timestamptz);
create table orders(id uuid primary key default gen_random_uuid(),customer_id uuid not null references profiles,merchant_id uuid not null references merchants,status text not null default 'received' check(status in ('received','accepted','preparing','ready','completed','cancelled','rejected')),payment_status text not null default 'pending' check(payment_status in ('pending','paid','failed','refunded')),pay_at_counter boolean default false,fulfilment text not null check(fulfilment in ('pickup','dine_in')),table_id uuid references merchant_tables,table_label text,pickup_code text not null,order_no text not null,client_request_id uuid not null,version int not null default 1,subtotal_minor int not null,tax_minor int not null,total_minor int not null,note text default '',items jsonb not null,history jsonb not null default '[]',created_at timestamptz not null default now(),unique(customer_id,client_request_id));
create table order_items(id uuid primary key default gen_random_uuid(),order_id uuid references orders,item_id uuid references menu_items,name text not null,unit_price_minor int not null,qty int not null check(qty between 1 and 99),variant_id text);
create table payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders unique,provider_order_id text unique,provider_payment_id text,status text not null default 'pending',created_at timestamptz default now());
create table payment_events(id uuid primary key default gen_random_uuid(),provider_event_id text unique not null,payload jsonb not null,created_at timestamptz default now());
create table order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid references orders,status text not null,actor_id uuid references profiles,reason text,created_at timestamptz default now());
create table order_counters(merchant_id uuid references merchants,day date,last_seq int not null,primary key(merchant_id,day));
create table audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references profiles,action text not null,entity_id uuid,created_at timestamptz default now());
create table rate_limits(subject uuid not null,bucket text not null,window_at timestamptz not null default now(),count int not null default 1,primary key(subject,bucket));
create index on orders(merchant_id,status,created_at desc);create index on orders(customer_id,created_at desc);create index on menu_items(merchant_id,in_stock);create index on merchants(campus_id,status);
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
create function public.owns(p_id uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from merchants where id=p_id and owner_id=auth.uid()) or is_admin()$$;
-- Restrict all direct writes. Public browse policies explicitly allow approved businesses only.
do $$declare t text;begin foreach t in array array['profiles','institutions','campuses','merchants','merchant_hours','menu_categories','menu_items','menu_variants','merchant_tables','orders','order_items','payments','payment_events','order_status_history','order_counters','audit_logs','rate_limits'] loop execute format('alter table %I enable row level security',t);execute format('revoke insert,update,delete on %I from anon,authenticated',t);end loop;end$$;
create policy profile_read on profiles for select to authenticated using(id=auth.uid() or is_admin());
create policy institutions_read on institutions for select using(true);create policy campus_read on campuses for select using(true);
create policy merchant_read on merchants for select using(status='approved' or owns(id));
create policy menu_read on menu_items for select using(exists(select 1 from merchants where id=merchant_id and (status='approved' or owns(id))));
create policy tables_read on merchant_tables for select using(exists(select 1 from merchants where id=merchant_id and (status='approved' or owns(id))));
create policy hours_read on merchant_hours for select using(exists(select 1 from merchants where id=merchant_id and (status='approved' or owns(id))));
create policy categories_read on menu_categories for select using(exists(select 1 from merchants where id=merchant_id and (status='approved' or owns(id))));
create policy variants_read on menu_variants for select using(exists(select 1 from menu_items where id=item_id));
create policy orders_read on orders for select to authenticated using(customer_id=auth.uid() or owns(merchant_id));
create policy order_items_read on order_items for select to authenticated using(exists(select 1 from orders where id=order_id));
create policy payments_read on payments for select to authenticated using(exists(select 1 from orders where id=order_id));
create policy history_read on order_status_history for select to authenticated using(exists(select 1 from orders where id=order_id));
create policy audit_read on audit_logs for select to authenticated using(is_admin());
create policy events_read on payment_events for select to authenticated using(is_admin());
create function handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,name,phone,role) values(new.id,coalesce(new.raw_user_meta_data->>'name','Customer'),new.phone,case when new.raw_user_meta_data->>'role'='merchant' then 'merchant' else 'customer' end);return new;end$$;
create trigger auth_profile after insert on auth.users for each row execute function handle_new_user();
create function update_profile(p_name text,p_email text) returns void language plpgsql security definer set search_path=public as $$begin if length(trim(p_name))<2 or length(p_name)>100 then raise exception 'Enter your full name';end if;update profiles set name=p_name,email=p_email where id=auth.uid();end$$;
create function create_order(p_input jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare m merchants; o orders; line jsonb; i menu_items; variant jsonb; snapshots jsonb='[]'; subtotal int=0; tax int; seq int; qty int; unit int; tbl merchant_tables; n int;begin
 if auth.uid() is null or not exists(select 1 from profiles where id=auth.uid() and role='customer') then raise exception 'Please use a customer account';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text || (p_input->>'client_request_id'),0));
 select * into o from orders where customer_id=auth.uid() and client_request_id=(p_input->>'client_request_id')::uuid;if found then return to_jsonb(o);end if;
 insert into rate_limits(subject,bucket) values(auth.uid(),'orders') on conflict(subject,bucket) do update set count=case when rate_limits.window_at<now()-interval '1 minute' then 1 else rate_limits.count+1 end,window_at=case when rate_limits.window_at<now()-interval '1 minute' then now() else rate_limits.window_at end returning count into n;if n>10 then raise exception 'Please wait a minute before ordering again';end if;
 select * into m from merchants where id=(p_input->>'merchant_id')::uuid for share;
 if not found or m.status<>'approved' or not m.accepting_orders then raise exception 'This eatery has paused orders';end if;
 if not (to_char(now() at time zone 'Asia/Kolkata','Dy')=any(m.open_days)) or (now() at time zone 'Asia/Kolkata')::time < split_part(replace(m.hours,'–','-'),'-',1)::time or (now() at time zone 'Asia/Kolkata')::time > split_part(replace(m.hours,'–','-'),'-',2)::time then raise exception 'This eatery is closed';end if;
 if p_input->>'fulfilment'='dine_in' then
 if not m.supports_dine_in then raise exception 'Table service is unavailable';end if;
 select * into tbl from merchant_tables where id=(p_input->>'table_id')::uuid and merchant_id=m.id and enabled and deleted_at is null for share;if not found then raise exception 'Choose an available table';end if;
 elsif p_input->>'fulfilment'<>'pickup' or not m.supports_pickup then raise exception 'Choose a valid service option';end if;
 if jsonb_typeof(p_input->'items')<>'array' or jsonb_array_length(p_input->'items') not between 1 and 100 then raise exception 'Review your cart';end if;
 for line in select * from jsonb_array_elements(p_input->'items') loop
 select * into i from menu_items where id=(line->>'item_id')::uuid and merchant_id=m.id and in_stock for share;if not found then raise exception 'An item is sold out. Review your cart';end if;
 qty=(line->>'qty')::int;if qty not between 1 and 99 then raise exception 'Choose a quantity from 1 to 99';end if;unit=i.price_minor;variant=null;
 if line->>'variant_id' is not null then select value into variant from jsonb_array_elements(i.variants) where value->>'id'=line->>'variant_id';if variant is null then raise exception 'Item option is unavailable';end if;unit=(variant->>'price_minor')::int;end if;
 snapshots=snapshots||jsonb_build_array(jsonb_build_object('item_id',i.id,'name',i.name||case when variant is not null then ' · '||(variant->>'name') else '' end,'qty',qty,'unit_price_minor',unit,'variant_id',line->>'variant_id'));subtotal=subtotal+qty*unit;
 end loop;tax=round(subtotal*0.05);
 insert into order_counters values(m.id,(now() at time zone 'Asia/Kolkata')::date,1) on conflict(merchant_id,day) do update set last_seq=order_counters.last_seq+1 returning last_seq into seq;
 insert into orders(customer_id,merchant_id,client_request_id,order_no,pickup_code,fulfilment,table_id,table_label,note,items,subtotal_minor,tax_minor,total_minor,history) values(auth.uid(),m.id,(p_input->>'client_request_id')::uuid,'A-'||lpad(seq::text,3,'0'),upper(substr(encode(gen_random_bytes(3),'hex'),1,4)),p_input->>'fulfilment',tbl.id,tbl.label,left(coalesce(p_input->>'note',''),500),snapshots,subtotal,tax,subtotal+tax,jsonb_build_array(jsonb_build_object('status','received','at',now()))) returning * into o;
 insert into order_items(order_id,item_id,name,unit_price_minor,qty,variant_id) select o.id,(x->>'item_id')::uuid,x->>'name',(x->>'unit_price_minor')::int,(x->>'qty')::int,x->>'variant_id' from jsonb_array_elements(snapshots) x;
 insert into order_status_history(order_id,status,actor_id) values(o.id,'received',auth.uid());return to_jsonb(o);end$$;
create function advance_order_status(p_order_id uuid,p_to_status text,p_expected_version int,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare o orders;begin
 select * into o from orders where id=p_order_id for update;if not found or not owns(o.merchant_id) then raise exception 'Not authorized';end if;
 if o.version<>p_expected_version then raise exception 'STALE';end if;
 if not ((o.status='received' and p_to_status in ('accepted','rejected','cancelled')) or (o.status='accepted' and p_to_status in ('preparing','rejected','cancelled')) or (o.status='preparing' and p_to_status='ready') or (o.status='ready' and p_to_status='completed')) then raise exception 'Invalid order transition';end if;
 if o.payment_status<>'paid' and (not o.pay_at_counter or p_to_status='completed') then raise exception 'Confirm payment first';end if;
 update orders set status=p_to_status,version=version+1,history=history||jsonb_build_array(jsonb_build_object('status',p_to_status,'at',now(),'reason',p_reason)) where id=p_order_id and version=p_expected_version returning * into o;if not found then raise exception 'STALE';end if;
 insert into order_status_history(order_id,status,actor_id,reason) values(o.id,p_to_status,auth.uid(),left(p_reason,500));return to_jsonb(o);end$$;
create function counter_payment(p_order_id uuid) returns void language plpgsql security definer set search_path=public as $$declare o orders;begin select * into o from orders where id=p_order_id for update;if o.customer_id=auth.uid() then if not exists(select 1 from merchants where id=o.merchant_id and pay_at_counter_enabled) or o.payment_status='paid' then raise exception 'Counter payment unavailable';end if;update orders set pay_at_counter=true,version=version+1 where id=o.id;elsif owns(o.merchant_id) and o.pay_at_counter then update orders set payment_status='paid',version=version+1 where id=o.id;insert into audit_logs(actor_id,action,entity_id) values(auth.uid(),'Counter payment confirmed',o.id);else raise exception 'Not authorized';end if;end$$;
create function approve_merchant(p_id uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$begin if not is_admin() then raise exception 'Administrator required';end if;update merchants set status=p_status,accepting_orders=(p_status='approved') where id=p_id;insert into audit_logs(actor_id,action,entity_id) values(auth.uid(),'Merchant status: '||p_status,p_id);end$$;
create function register_merchant(p_input jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare m merchants;t jsonb;begin if not exists(select 1 from profiles where id=auth.uid() and role='merchant') then raise exception 'Partner account required';end if;if length(trim(p_input->>'name'))<2 then raise exception 'Business name required';end if;insert into merchants(owner_id,slug,name,category,building,address,city,state,pin,campus,is_on_campus,hours,avg_prep_minutes,supports_pickup,supports_dine_in,pay_at_counter_enabled) values(auth.uid(),lower(regexp_replace(p_input->>'name','[^a-zA-Z0-9]+','-','g'))||'-'||substr(gen_random_uuid()::text,1,5),p_input->>'name',p_input->>'category',p_input->>'building',p_input->>'address',p_input->>'city',p_input->>'state',p_input->>'pin',p_input->>'campus',(p_input->>'is_on_campus')::boolean,p_input->>'hours',(p_input->>'avg_prep_minutes')::int,(p_input->>'supports_pickup')::boolean,(p_input->>'supports_dine_in')::boolean,(p_input->>'pay_at_counter_enabled')::boolean) returning * into m;
 for t in select * from jsonb_array_elements(coalesce(p_input->'tables','[]')) loop insert into merchant_tables(id,merchant_id,label,enabled) values((t->>'id')::uuid,m.id,t->>'label',true);end loop;return to_jsonb(m);end$$;
create function update_merchant(p_id uuid,p_input jsonb) returns void language plpgsql security definer set search_path=public as $$declare t jsonb;begin if not owns(p_id) then raise exception 'Not authorized';end if;update merchants set name=coalesce(p_input->>'name',name),building=coalesce(p_input->>'building',building),hours=coalesce(p_input->>'hours',hours),open_days=case when p_input ? 'open_days' then array(select jsonb_array_elements_text(p_input->'open_days')) else open_days end,avg_prep_minutes=coalesce((p_input->>'avg_prep_minutes')::int,avg_prep_minutes),rush_extra_minutes=coalesce((p_input->>'rush_extra_minutes')::int,rush_extra_minutes),accepting_orders=coalesce((p_input->>'accepting_orders')::boolean,accepting_orders),supports_pickup=coalesce((p_input->>'supports_pickup')::boolean,supports_pickup),supports_dine_in=coalesce((p_input->>'supports_dine_in')::boolean,supports_dine_in),pay_at_counter_enabled=coalesce((p_input->>'pay_at_counter_enabled')::boolean,pay_at_counter_enabled) where id=p_id;
 for t in select * from jsonb_array_elements(coalesce(p_input->'tables','[]')) loop if exists(select 1 from merchant_tables where id=(t->>'id')::uuid and merchant_id<>p_id) then raise exception 'Table belongs to another business';end if;insert into merchant_tables(id,merchant_id,label,enabled,deleted_at) values((t->>'id')::uuid,p_id,t->>'label',(t->>'enabled')::boolean,(t->>'deleted_at')::timestamptz) on conflict(id) do update set label=excluded.label,enabled=excluded.enabled,deleted_at=excluded.deleted_at;end loop;end$$;
create function upsert_menu_item(p_item jsonb) returns void language plpgsql security definer set search_path=public as $$declare v jsonb;begin if not owns((p_item->>'merchant_id')::uuid) then raise exception 'Not authorized';end if;if exists(select 1 from menu_items where id=(p_item->>'id')::uuid and merchant_id<>(p_item->>'merchant_id')::uuid) then raise exception 'Item belongs to another business';end if;if length(trim(p_item->>'name'))<1 then raise exception 'Item name required';end if;for v in select * from jsonb_array_elements(coalesce(p_item->'variants','[]')) loop if (v->>'price_minor')::int<1 or length(v->>'name')<1 then raise exception 'Invalid variant';end if;end loop;
 insert into menu_items(id,merchant_id,name,description,category,price_minor,is_veg,in_stock,image,variants) values((p_item->>'id')::uuid,(p_item->>'merchant_id')::uuid,p_item->>'name',p_item->>'description',p_item->>'category',(p_item->>'price_minor')::int,(p_item->>'is_veg')::boolean,(p_item->>'in_stock')::boolean,p_item->>'image',coalesce(p_item->'variants','[]')) on conflict(id) do update set name=excluded.name,description=excluded.description,category=excluded.category,price_minor=excluded.price_minor,is_veg=excluded.is_veg,in_stock=excluded.in_stock,image=excluded.image,variants=excluded.variants;end$$;
create function set_item_stock(p_id uuid,p_stock boolean) returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from menu_items where id=p_id and owns(merchant_id)) then raise exception 'Not authorized';end if;update menu_items set in_stock=p_stock where id=p_id;end$$;
-- All privileged functions are opt-in; anonymous users never execute mutations.
revoke execute on all functions in schema public from public,anon;
grant execute on function is_admin(),owns(uuid) to anon,authenticated;
grant execute on function update_profile(text,text),create_order(jsonb),advance_order_status(uuid,text,int,text),counter_payment(uuid),approve_merchant(uuid,text),register_merchant(jsonb),update_merchant(uuid,jsonb),upsert_menu_item(jsonb),set_item_stock(uuid,boolean) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('menu-images','menu-images',true,2097152,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy menu_image_read on storage.objects for select using(bucket_id='menu-images');
create policy menu_image_upload on storage.objects for insert to authenticated with check(bucket_id='menu-images' and owns((storage.foldername(name))[1]::uuid));
alter publication supabase_realtime add table orders,menu_items,merchants;
